import {
    useId, useRef, useState,
    type ComponentProps, type FormEvent, type ReactNode,
} from "react";
import { Button } from "./button";
import { Input } from "./input";
import { NativeSelect } from "./native-select";
import { cn } from "./utils";
import type { TaskDueDate, TaskItemAssignee } from "./task-item";

type SubtaskItemData = {
    id: string;
    title: string;
    parentId: string | null;
    completed: boolean;
    assignee: TaskItemAssignee | null;
    dueDate: TaskDueDate | null;
};

type SubtaskItemPatch = Partial<Pick<
    SubtaskItemData,
    "completed" | "assignee" | "dueDate"
>>;

type SubtaskCreateDraft = {
    title: string;
    parentId: string | null;
    assignee: TaskItemAssignee | null;
    dueDate: TaskDueDate | null;
};

type SubtaskMoveRequest = {
    taskId: string;
    parentId: string | null;
    index: number;
};

type SubtaskMutation =
    | { type: "update"; taskId: string; patch: SubtaskItemPatch }
    | { type: "move"; request: SubtaskMoveRequest };

type SubtaskListProps = Omit<
    ComponentProps<"section">,
    "children" | "aria-label"
> & {
    parentTaskId: string;
    subtasks: readonly SubtaskItemData[];
    people: readonly TaskItemAssignee[];
    onCreate: (draft: SubtaskCreateDraft) => void | Promise<void>;
    onUpdate: (
        taskId: string,
        patch: SubtaskItemPatch,
    ) => void | Promise<void>;
    onMove: (request: SubtaskMoveRequest) => void | Promise<void>;
    label?: string;
    disabled?: boolean;
    emptyText?: string;
    saveErrorMessage?: string;
    createErrorMessage?: string;
};

type SubtaskDraftValues = {
    completed?: boolean;
    parentId?: string | null;
    assignee?: TaskItemAssignee | null;
    dueDate?: TaskDueDate | null;
};

function validateSubtasks(
    parentTaskId: string,
    subtasks: readonly SubtaskItemData[],
    people: readonly TaskItemAssignee[],
) {
    if (!parentTaskId.trim()) {
        throw new Error("SubtaskList requires a parent task ID.");
    }
    const itemsById = new Map<string, SubtaskItemData>();
    for (const item of subtasks) {
        if (!item.id.trim() || !item.title.trim() ||
            typeof item.completed !== "boolean") {
            throw new Error("SubtaskList items need IDs, titles and completion state.");
        }
        if (item.id === parentTaskId || itemsById.has(item.id)) {
            throw new Error("SubtaskList item IDs must be unique and not its parent ID.");
        }
        if (item.assignee && (item.assignee.kind !== "person" ||
            !item.assignee.id.trim() || !item.assignee.title.trim())) {
            throw new Error("SubtaskList assignees must be named people.");
        }
        if (item.dueDate && (!item.dueDate.value.trim() ||
            !item.dueDate.label.trim())) {
            throw new Error("SubtaskList due dates need values and labels.");
        }
        itemsById.set(item.id, item);
    }

    const personIds = new Set<string>();
    for (const person of people) {
        if (person.kind !== "person" || !person.id.trim() ||
            !person.title.trim() || personIds.has(person.id)) {
            throw new Error("SubtaskList people need unique named person IDs.");
        }
        personIds.add(person.id);
    }

    for (const item of subtasks) {
        if (item.parentId !== null && !itemsById.has(item.parentId)) {
            throw new Error(
                `SubtaskList parent does not exist: ${item.parentId}`,
            );
        }
    }

    for (const item of subtasks) {
        const ancestors = new Set<string>([item.id]);
        let parentId = item.parentId;
        while (parentId !== null) {
            if (ancestors.has(parentId)) {
                throw new Error("SubtaskList hierarchy cannot contain cycles.");
            }
            ancestors.add(parentId);
            parentId = itemsById.get(parentId)!.parentId;
        }
    }
}

function getDescendantIds(
    taskId: string,
    subtasks: readonly SubtaskItemData[],
) {
    const descendants = new Set<string>();
    const parents = [taskId];
    while (parents.length) {
        const parentId = parents.pop()!;
        for (const item of subtasks) {
            if (item.parentId !== parentId || descendants.has(item.id)) continue;
            descendants.add(item.id);
            parents.push(item.id);
        }
    }
    return descendants;
}

function SubtaskList({
    parentTaskId,
    subtasks,
    people,
    onCreate,
    onUpdate,
    onMove,
    label = "하위 작업",
    disabled = false,
    emptyText = "하위 작업이 없습니다.",
    saveErrorMessage = "하위 작업을 저장하지 못했습니다. 다시 시도하세요.",
    createErrorMessage = "하위 작업을 만들지 못했습니다. 입력 내용은 보존했습니다.",
    className,
    ...props
}: SubtaskListProps) {
    const generatedId = useId();
    const pendingIds = useRef(new Set<string>());
    const pendingMoveRef = useRef<string | null>(null);
    const createPending = useRef(false);
    const [drafts, setDrafts] = useState<Record<string, SubtaskDraftValues>>({});
    const [failedMutations, setFailedMutations] = useState<
        Record<string, SubtaskMutation>
    >({});
    const [itemErrors, setItemErrors] = useState<Record<string, string>>({});
    const [pendingItems, setPendingItems] = useState<Set<string>>(new Set());
    const [pendingMoveId, setPendingMoveId] = useState<string | null>(null);
    const [createDraft, setCreateDraft] = useState<SubtaskCreateDraft>({
        title: "",
        parentId: null,
        assignee: null,
        dueDate: null,
    });
    const [createError, setCreateError] = useState<string | null>(null);
    const [createIsPending, setCreateIsPending] = useState(false);

    validateSubtasks(parentTaskId, subtasks, people);

    async function runMutation(taskId: string, mutation: SubtaskMutation) {
        if (disabled || pendingIds.current.has(taskId)) return;
        if (mutation.type === "move" && (
            pendingMoveRef.current !== null ||
            Object.entries(failedMutations).some(([failedTaskId, failed]) =>
                failed.type === "move" && failedTaskId !== taskId,
            )
        )) return;
        if (mutation.type === "move") {
            pendingMoveRef.current = taskId;
            setPendingMoveId(taskId);
        }
        pendingIds.current.add(taskId);
        setPendingItems((current) => new Set(current).add(taskId));
        setItemErrors((current) => ({ ...current, [taskId]: "" }));
        setFailedMutations((current) => ({ ...current, [taskId]: mutation }));
        try {
            if (mutation.type === "update") {
                await onUpdate(taskId, mutation.patch);
            } else {
                await onMove(mutation.request);
            }
            setDrafts((current) => {
                const next = { ...current };
                delete next[taskId];
                return next;
            });
            setFailedMutations((current) => {
                const next = { ...current };
                delete next[taskId];
                return next;
            });
            setItemErrors((current) => {
                const next = { ...current };
                delete next[taskId];
                return next;
            });
        } catch {
            setItemErrors((current) => ({
                ...current,
                [taskId]: saveErrorMessage,
            }));
        } finally {
            pendingIds.current.delete(taskId);
            if (pendingMoveRef.current === taskId) {
                pendingMoveRef.current = null;
                setPendingMoveId(null);
            }
            setPendingItems((current) => {
                const next = new Set(current);
                next.delete(taskId);
                return next;
            });
        }
    }

    function savePatch(task: SubtaskItemData, patch: SubtaskItemPatch) {
        setDrafts((current) => ({
            ...current,
            [task.id]: { ...current[task.id], ...patch },
        }));
        setItemErrors((current) => ({ ...current, [task.id]: "" }));
        void runMutation(task.id, { type: "update", taskId: task.id, patch });
    }

    function moveTask(request: SubtaskMoveRequest) {
        if (disabled || pendingMoveRef.current !== null ||
            Object.values(failedMutations).some((mutation) =>
                mutation.type === "move",
            )) return;
        setDrafts((current) => ({
            ...current,
            [request.taskId]: {
                ...current[request.taskId],
                parentId: request.parentId,
            },
        }));
        setItemErrors((current) => ({ ...current, [request.taskId]: "" }));
        void runMutation(request.taskId, { type: "move", request });
    }

    async function createSubtask(event: FormEvent<HTMLFormElement>) {
        event.preventDefault();
        if (disabled || createPending.current) return;
        if (!createDraft.title.trim()) {
            setCreateError("하위 작업 이름을 입력하세요.");
            return;
        }
        createPending.current = true;
        setCreateIsPending(true);
        setCreateError(null);
        try {
            await onCreate({
                ...createDraft,
                title: createDraft.title.trim(),
            });
            setCreateDraft({
                title: "",
                parentId: null,
                assignee: null,
                dueDate: null,
            });
        } catch {
            setCreateError(createErrorMessage);
        } finally {
            createPending.current = false;
            setCreateIsPending(false);
        }
    }

    const childrenByParent = new Map<string | null, SubtaskItemData[]>();
    for (const item of subtasks) {
        const siblings = childrenByParent.get(item.parentId) ?? [];
        siblings.push(item);
        childrenByParent.set(item.parentId, siblings);
    }
    const structureLocked = pendingMoveId !== null ||
        Object.values(failedMutations).some((mutation) =>
            mutation.type === "move",
        );

    function renderItems(parentId: string | null): ReactNode {
        const children = childrenByParent.get(parentId) ?? [];
        if (!children.length) return null;
        return (
            <ul className="m-0 grid list-none gap-2 p-0">
                {children.map((task) => {
                    const draft = drafts[task.id] ?? {};
                    const completed = draft.completed ?? task.completed;
                    const assignee = Object.hasOwn(draft, "assignee")
                        ? draft.assignee ?? null : task.assignee;
                    const dueDate = Object.hasOwn(draft, "dueDate")
                        ? draft.dueDate ?? null : task.dueDate;
                    const parent = Object.hasOwn(draft, "parentId")
                        ? draft.parentId ?? null : task.parentId;
                    const itemDisabled = disabled ||
                        pendingItems.has(task.id) || !!itemErrors[task.id];
                    const siblings = childrenByParent.get(task.parentId) ?? [];
                    const index = siblings.findIndex((item) => item.id === task.id);
                    const canMoveUp = index > 0;
                    const canMoveDown = index >= 0 && index < siblings.length - 1;
                    const forbiddenParents = getDescendantIds(task.id, subtasks);
                    forbiddenParents.add(task.id);
                    const parentOptions = subtasks.filter((item) =>
                        !forbiddenParents.has(item.id),
                    );
                    const dateInputId = `${generatedId}-${encodeURIComponent(task.id)}-due`;
                    const assigneeInputId = `${generatedId}-${encodeURIComponent(task.id)}-assignee`;
                    const parentInputId = `${generatedId}-${encodeURIComponent(task.id)}-parent`;
                    const failure = itemErrors[task.id];
                    const mutation = failedMutations[task.id];

                    return (
                        <li key={task.id} data-task-id={task.id}
                            className="grid min-w-0 gap-2">
                            <div className={
                                "grid min-w-0 gap-3 rounded-sm border " +
                                "border-border bg-surface p-[var(--space-3)]"
                            }>
                                <div className="flex min-w-0 flex-wrap items-center gap-3">
                                    <label className="inline-flex min-w-0 items-center gap-2">
                                        <input type="checkbox"
                                            aria-label={`${task.title} 완료`}
                                            checked={completed}
                                            disabled={itemDisabled}
                                            onChange={(event) => savePatch(task, {
                                                completed: event.currentTarget.checked,
                                            })}
                                            className="size-4 accent-[var(--accent)]" />
                                        <span className={cn(
                                            "min-w-0 break-words text-sm font-medium",
                                            completed && "text-muted line-through",
                                        )}>{task.title}</span>
                                    </label>
                                    <span className="ml-auto text-xs text-muted">
                                        #{task.id}
                                    </span>
                                </div>
                                <div className="grid min-w-0 gap-3 @md:grid-cols-2">
                                    <div className="grid min-w-0 gap-1">
                                        <label htmlFor={assigneeInputId}
                                            className="text-xs text-muted">
                                            담당자
                                        </label>
                                        <NativeSelect id={assigneeInputId}
                                            aria-label={`${task.title} 담당자`}
                                            value={assignee?.id ?? ""}
                                            disabled={itemDisabled}
                                            onChange={(event) => {
                                                const person = people.find((item) =>
                                                    item.id === event.currentTarget.value,
                                                ) ?? null;
                                                savePatch(task, { assignee: person });
                                            }}>
                                            <option value="">담당자 없음</option>
                                            {assignee && !people.some((person) =>
                                                person.id === assignee.id,
                                            ) && (
                                                <option value={assignee.id}>
                                                    {assignee.title} (목록에서 확인 불가)
                                                </option>
                                            )}
                                            {people.map((person) => (
                                                <option key={person.id}
                                                    value={person.id}>
                                                    {person.title}
                                                </option>
                                            ))}
                                        </NativeSelect>
                                    </div>
                                    <div className="grid min-w-0 gap-1">
                                        <label htmlFor={dateInputId}
                                            className="text-xs text-muted">
                                            기한
                                        </label>
                                        <Input id={dateInputId}
                                            aria-label={`${task.title} 기한`}
                                            type="date"
                                            value={dueDate?.value ?? ""}
                                            disabled={itemDisabled}
                                            onChange={(event) => {
                                                const value = event.currentTarget.value;
                                                savePatch(task, {
                                                    dueDate: value
                                                        ? { value, label: value }
                                                        : null,
                                                });
                                            }} />
                                    </div>
                                    <div className="grid min-w-0 gap-1 @md:col-span-2">
                                        <label htmlFor={parentInputId}
                                            className="text-xs text-muted">
                                            상위 작업
                                        </label>
                                        <NativeSelect id={parentInputId}
                                            aria-label={`${task.title} 상위 작업`}
                                            value={parent ?? ""}
                                            disabled={itemDisabled || structureLocked}
                                            onChange={(event) => {
                                                const nextParentId =
                                                    event.currentTarget.value || null;
                                                if (nextParentId === parent) return;
                                                if (nextParentId !== null &&
                                                    forbiddenParents.has(nextParentId)) {
                                                    return;
                                                }
                                                const destination = subtasks.filter(
                                                    (item) => item.id !== task.id &&
                                                        item.parentId === nextParentId,
                                                );
                                                moveTask({
                                                    taskId: task.id,
                                                    parentId: nextParentId,
                                                    index: destination.length,
                                                });
                                            }}>
                                            <option value="">
                                                #{parentTaskId} (루트 작업)
                                            </option>
                                            {parentOptions.map((option) => (
                                                <option key={option.id}
                                                    value={option.id}>
                                                    {option.title}
                                                </option>
                                            ))}
                                        </NativeSelect>
                                    </div>
                                </div>
                                <div role="group"
                                    aria-label={`${task.title} 순서 변경`}
                                    className="flex flex-wrap gap-2">
                                    <Button type="button" variant="outline"
                                        aria-label={`${task.title} 위로 이동`}
                                        disabled={itemDisabled || structureLocked ||
                                            !canMoveUp}
                                        onClick={() => moveTask({
                                            taskId: task.id,
                                            parentId: task.parentId,
                                            index: index - 1,
                                        })}>
                                        위로 이동
                                    </Button>
                                    <Button type="button" variant="outline"
                                        aria-label={`${task.title} 아래로 이동`}
                                        disabled={itemDisabled || structureLocked ||
                                            !canMoveDown}
                                        onClick={() => moveTask({
                                            taskId: task.id,
                                            parentId: task.parentId,
                                            index: index + 1,
                                        })}>
                                        아래로 이동
                                    </Button>
                                </div>
                                {failure && (
                                    <div className="grid gap-2">
                                        <p role="alert" className="m-0 text-sm text-danger">
                                            {failure}
                                            {mutation?.type === "move" &&
                                                ` (요청 위치 ${mutation.request.index + 1})`}
                                        </p>
                                        <div className="flex flex-wrap gap-2">
                                            <Button type="button" variant="outline"
                                                disabled={disabled ||
                                                    pendingItems.has(task.id)}
                                                onClick={() => {
                                                    if (mutation) {
                                                        void runMutation(task.id, mutation);
                                                    }
                                                }}>
                                                다시 저장
                                            </Button>
                                            <Button type="button" variant="ghost"
                                                disabled={disabled ||
                                                    pendingItems.has(task.id)}
                                                onClick={() => {
                                                    setDrafts((current) => {
                                                        const next = { ...current };
                                                        delete next[task.id];
                                                        return next;
                                                    });
                                                    setFailedMutations((current) => {
                                                        const next = { ...current };
                                                        delete next[task.id];
                                                        return next;
                                                    });
                                                    setItemErrors((current) => {
                                                        const next = { ...current };
                                                        delete next[task.id];
                                                        return next;
                                                    });
                                                }}>
                                                초안 취소
                                            </Button>
                                        </div>
                                    </div>
                                )}
                            </div>
                            {renderItems(task.id)}
                        </li>
                    );
                })}
            </ul>
        );
    }

    return (
        <section {...props} aria-label={label}
            aria-busy={pendingMoveId !== null || undefined}
            className={cn("@container grid min-w-0 gap-4", className)}>
            <header className="flex min-w-0 items-baseline justify-between gap-3">
                <h2 className="m-0 text-base font-semibold text-foreground">
                    {label}
                </h2>
                <span className="text-xs text-muted">
                    {subtasks.length}개 하위 작업 · #{parentTaskId}
                </span>
            </header>
            {pendingMoveId !== null && (
                <p role="status" className="m-0 text-sm text-muted">
                    작업 계층을 저장하는 중입니다.
                </p>
            )}
            {subtasks.length === 0 ? (
                <p className="m-0 text-sm text-muted">{emptyText}</p>
            ) : renderItems(null)}
            <form onSubmit={(event) => void createSubtask(event)}
                aria-label={`${label} 추가`}
                className={
                    "grid min-w-0 gap-3 rounded-sm border border-border " +
                    "bg-surface-subtle p-[var(--space-3)]"
                }>
                <label htmlFor={`${generatedId}-new-title`}
                    className="text-sm font-medium text-foreground">
                    새 하위 작업
                </label>
                <Input id={`${generatedId}-new-title`}
                    aria-label="새 하위 작업 이름"
                    value={createDraft.title}
                    disabled={disabled || createIsPending}
                    onChange={(event) => {
                        const title = event.currentTarget.value;
                        setCreateDraft((current) => ({
                            ...current,
                            title,
                        }));
                        setCreateError(null);
                    }} />
                <div className="grid min-w-0 gap-3 @md:grid-cols-2">
                    <div className="grid min-w-0 gap-1">
                        <label htmlFor={`${generatedId}-new-parent`}
                            className="text-xs text-muted">
                            상위 작업
                        </label>
                        <NativeSelect id={`${generatedId}-new-parent`}
                            aria-label="새 하위 작업 상위 작업"
                            value={createDraft.parentId ?? ""}
                            disabled={disabled || createIsPending}
                            onChange={(event) => {
                                const parentId = event.currentTarget.value || null;
                                setCreateDraft((current) => ({
                                    ...current,
                                    parentId,
                                }));
                            }}>
                            <option value="">#{parentTaskId} (루트 작업)</option>
                            {subtasks.map((item) => (
                                <option key={item.id} value={item.id}>
                                    {item.title}
                                </option>
                            ))}
                        </NativeSelect>
                    </div>
                    <div className="grid min-w-0 gap-1">
                        <label htmlFor={`${generatedId}-new-assignee`}
                            className="text-xs text-muted">
                            담당자
                        </label>
                        <NativeSelect id={`${generatedId}-new-assignee`}
                            aria-label="새 하위 작업 담당자"
                            value={createDraft.assignee?.id ?? ""}
                            disabled={disabled || createIsPending}
                            onChange={(event) => {
                                const selectedPersonId = event.currentTarget.value;
                                const assignee = people.find((person) =>
                                    person.id === selectedPersonId,
                                ) ?? null;
                                setCreateDraft((current) => ({
                                    ...current,
                                    assignee,
                                }));
                            }}>
                            <option value="">담당자 없음</option>
                            {people.map((person) => (
                                <option key={person.id} value={person.id}>
                                    {person.title}
                                </option>
                            ))}
                        </NativeSelect>
                    </div>
                    <div className="grid min-w-0 gap-1 @md:col-span-2">
                        <label htmlFor={`${generatedId}-new-due`}
                            className="text-xs text-muted">
                            기한
                        </label>
                        <Input id={`${generatedId}-new-due`}
                            aria-label="새 하위 작업 기한"
                            type="date"
                            value={createDraft.dueDate?.value ?? ""}
                            disabled={disabled || createIsPending}
                            onChange={(event) => {
                                const value = event.currentTarget.value;
                                setCreateDraft((current) => ({
                                    ...current,
                                    dueDate: value ? { value, label: value } : null,
                                }));
                            }} />
                    </div>
                </div>
                {createError && (
                    <p role="alert" className="m-0 text-sm text-danger">
                        {createError}
                    </p>
                )}
                <Button type="submit" variant="outline"
                    disabled={disabled || createIsPending}>
                    {createIsPending ? "추가 중…" : "하위 작업 추가"}
                </Button>
            </form>
        </section>
    );
}

export { SubtaskList };
export type {
    SubtaskCreateDraft,
    SubtaskItemData,
    SubtaskItemPatch,
    SubtaskListProps,
    SubtaskMoveRequest,
};
